def text_plot(f, xmin, xmax, ymin, ymax):
    # Prints the graph of f: a column for each whole number x, a row for each whole number y
    for y in range(ymax, ymin - 1, -1):
        row = ""
        for x in range(xmin, xmax + 1):
            if y - 0.5 <= f(x) < y + 0.5:
                mark = "*"
            elif x == 0 and y == 0:
                mark = "+"
            elif x == 0:
                mark = "|"
            elif y == 0:
                mark = "-"
            else:
                mark = "."
            row = row + mark + " "
        print(row)


from fractions import Fraction

cases = [
    ("two points, a whole slope", 1, -1, 3, 5),
    ("a fraction slope", -2, 1, 4, 5),
    ("a negative slope", -1, 3, 2, -3),
    ("a horizontal line", -3, 2, 4, 2),
]
for label, x1, y1, x2, y2 in cases:
    m = Fraction(y2 - y1, x2 - x1)
    b = y1 - m * x1
    print(f"{label}: ({x1}, {y1}) and ({x2}, {y2})")
    print(f"  slope m = ({y2} - ({y1})) / ({x2} - ({x1})) = {m}")
    print(f"  point-slope: y - ({y1}) = ({m})(x - ({x1}))")
    print(f"  b = {y1} - ({m})({x1}) = {b}, so y = ({m})x + ({b})")
    print(f"  check: at x = {x2}, y = {m * x2 + b}")
text_plot(lambda x: Fraction(2, 3) * x + Fraction(7, 3), -4, 4, -2, 5)
